list_currencies.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.currencies().listCurrencies(Map.of("search", "dollar", "active", true));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("currencies")) {
    Map<?, ?> currency = (Map<?, ?>) row;
    System.out.println(currency.get("id") + " " + currency.get("code") + " " + currency.get("name") + " " + currency.get("base"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

